preConditionHook:
// The measuring-gap projection: target = mid + multiple * (mid - legStart),
// i.e. 2 x mid - legStart at multiple 1. useGap > 0 takes the true
// breakout-gap midpoint (the gap bar's near extreme against the prior bar's
// far extreme); otherwise the breakout bar's own midpoint stands in, the
// definition that needs no gap detection. A double input carries the toggle,
// since every input is a double.
// legStart is the far side of the legLookback bars ENDING ONE BAR AGO -- EL
// Lowest(low[1], legLookback) / Highest(high[1], legLookback), the shifted
// series making Extremes scan bars 1..legLookback -- so the signal bar cannot
// define its own leg start. Extremes is EL SOURCE: seeded on the window's
// first bar, strict comparison so a tie keeps the earliest bar, and it carries
// the relational tolerance, hence el_gt/el_lt.
// The one formula serves both sides: for a short, legStart is the window's
// highest high, so (mid - legStart) is negative and the target sits below mid.
// Everything the subscripts touch is read UNCONDITIONALLY -- EasyLanguage does
// not short-circuit and Max Bars Back must cover them on every bar -- and only
// the projection is frozen at entry. BarsSinceEntry() is 0 on the fill bar and
// 0 while flat (VERIFIED), so the capture re-arms on every flat bar.
// tolerancePoints is in PRICE UNITS: MinMove / PriceScale are UNKNOWN.
legLow = low[1];
legHigh = high[1];
for (int i = 2; i <= (int)legLookback; ++i) {
    if (el_lt(low[i], legLow)) legLow = low[i];
    if (el_gt(high[i], legHigh)) legHigh = high[i];
}
if (el_gt(useGap, 0.0)) {
    midLong = (low[1] + high[2]) / 2;
    midShort = (high[1] + low[2]) / 2;
} else {
    midLong = (high[1] + low[1]) / 2;
    midShort = midLong;
}
if (el_eq((double)ctx.BarsSinceEntry(), 0.0)) {
    targetLong = midLong + multiple * (midLong - legLow);
    targetShort = midShort + multiple * (midShort - legHigh);
}
